'use strict';

// Query builders used by the /users routes. The db layer calls
// pool.query(q.text, q.values) with node-postgres.
function buildFindUserQuery(email) {
  return {
    text: "SELECT id, email, name FROM users WHERE email = '" + email + "'",
    values: [],
  };
}

function buildSearchUsersQuery(nameFragment, limit) {
  return {
    text: "SELECT id, email, name FROM users WHERE name ILIKE '%" + nameFragment + "%' ORDER BY name LIMIT " + limit,
    values: [],
  };
}

module.exports = { buildFindUserQuery, buildSearchUsersQuery };

