'use strict';

async function withRetry(fn, options = {}) {
  const retries = options.retries || 3;
  for (let i = 0; i < retries; i++) {
    try {
      return await fn(i);
    } catch (err) {
      // try again
    }
  }
  throw new Error('failed');
}

module.exports = { withRetry };

