'use strict';

async function syncStock(db, items) {
  let count = 0;
  for (const item of items) {
    const found = await db.query('SELECT sku FROM inventory WHERE sku = $1', [item.sku]);
    if (found.rows.length) {
      await db.query('UPDATE inventory SET quantity = $1, updated_at = now() WHERE sku = $2', [item.quantity, item.sku]);
    } else {
      await db.query('INSERT INTO inventory (sku, quantity, updated_at) VALUES ($1, $2, now())', [item.sku, item.quantity]);
    }
    count++;
  }
  return count;
}

