'use strict';

function createExtractor({ readFile, parse }) {
  const cache = new Map();
  let hits = 0;
  let misses = 0;
  return {
    extract(filePath) {
      if (cache.has(filePath)) {
        hits++;
        return cache.get(filePath);
      }
      misses++;
      const result = parse(readFile(filePath).toString('utf8'));
      cache.set(filePath, result);
      return result;
    },
    stats: () => ({ hits, misses }),
  };
}

module.exports = { createExtractor };

