'use strict';

function addItem(cart, item) {
  const existing = cart.items.find(i => i.sku === item.sku);
  if (existing) existing.quantity += item.quantity;
  else cart.items.push(item);
  return cart;
}

function removeItem(cart, sku) {
  cart.items = cart.items.filter(i => i.sku !== sku);
  return cart;
}

function applyDiscount(cart, pct) {
  cart.discountPct = pct;
  return cart;
}

function total(cart) {
  const sum = cart.items.reduce((acc, i) => acc + i.price * i.quantity, 0);
  return Math.round(sum * (1 - (cart.discountPct || 0) / 100) * 100) / 100;
}

module.exports = { addItem, removeItem, applyDiscount, total };

